<?php
declare(strict_types=1);

function r19_staff(App $app,int $tenant):array {
    return $app->all('SELECT u.id,u.name,u.email,u.username_r17,u.role FROM users u WHERE u.tenant_id=? AND u.is_active=1 AND u.role IN("tenant_admin","manager","editor","cashier","kitchen") AND NOT EXISTS(SELECT 1 FROM fisitaap_employees_r17 e WHERE e.tenant_id=u.tenant_id AND e.user_id=u.id AND e.is_active=0) ORDER BY COALESCE(NULLIF(u.username_r17,""),u.name),u.id',[$tenant]);
}
function r19_users_save(App $app,array $actor,array $tenant,array $form):int {
    qa180_permission($app,$actor,'usuarios','write');$app->db->beginTransaction();
    try{
        $app->one('SELECT id FROM tenants WHERE id=? FOR UPDATE',[$tenant['id']]);$id=(int)($form['id']??0);$old=$id?$app->one('SELECT * FROM users WHERE id=? AND tenant_id=? AND role IN("tenant_admin","manager","editor","cashier","kitchen") FOR UPDATE',[$id,$tenant['id']]):null;if($id&&!$old)throw new DomainException('Usuario no disponible en este negocio.');
        $owner=$old&&$old['role']==='tenant_admin';if($owner&&(int)$actor['id']!==$id)throw new DomainException('El dueño edita su propio acceso.');
        $eid=(int)($form['employee_id']??0);$employee=$eid?$app->one('SELECT * FROM fisitaap_employees_r17 WHERE id=? AND tenant_id=? FOR UPDATE',[$eid,$tenant['id']]):null;
        if(!$id&&!$employee)throw new DomainException('Registra primero al empleado en Control de personal y selecciónalo aquí.');
        if($eid&&!$employee)throw new DomainException('Selecciona un empleado de este negocio.');
        if($employee&&$employee['user_id']&&(int)$employee['user_id']!==$id)throw new DomainException('Este empleado ya tiene otro usuario. Edita ese acceso.');
        $linked=$old?$app->one('SELECT id FROM fisitaap_employees_r17 WHERE tenant_id=? AND user_id=?',[$tenant['id'],$id]):null;if($linked&&$eid!==(int)$linked['id'])throw new DomainException('Este acceso ya está vinculado a su empleado. Conserva esa relación.');
        $active=$owner?1:(isset($form['is_active'])?1:0);if($active&&$employee&&!$employee['is_active'])throw new DomainException('Activa primero el expediente del empleado.');
        $email=mb_strtolower(trim((string)($form['email']??'')));r17_email_unique($app,$email,$id);$alias=mb_strtolower(trim((string)($form['username']??'')));if(!preg_match('/^[a-z][a-z0-9._-]{2,79}$/D',$alias)||$app->one('SELECT id FROM users WHERE tenant_id=? AND username_r17=? AND id<>?',[$tenant['id'],$alias,$id]))throw new DomainException('Usa un nombre rápido único en tu negocio, empezando por una letra (3 a 80 caracteres).');
        $role=$owner?'tenant_admin':(string)($form['role']??'cashier');if(!in_array($role,['tenant_admin','manager','editor','cashier','kitchen'],true)||(!$owner&&$role==='tenant_admin')||($role==='kitchen'&&!r17_menu($tenant)))throw new DomainException('Selecciona un perfil válido.');
        $password=(string)($form['password']??'');if((!$old||$password!=='')&&(strlen($password)<4||strlen($password)>72))throw new DomainException('La contraseña debe tener de 4 a 72 caracteres.');
        $name=$employee?$employee['name_r19']:($old['name']??'');$phone=$employee?($employee['phone']??''):($old['phone']??'');
        if($old){$assigned=$app->one('SELECT previous_role FROM fisitaap_r1_user_roles WHERE tenant_id=? AND user_id=?',[$tenant['id'],$id]);$actualRole=$assigned?'manager':$role;$app->exec('UPDATE users SET name=?,phone=?,email=?,username_r17=?,role=?,is_active=? WHERE id=? AND tenant_id=?',[$name,$phone,$email,$alias,$actualRole,$active,$id,$tenant['id']]);if($assigned)$app->exec('UPDATE fisitaap_r1_user_roles SET previous_role=? WHERE tenant_id=? AND user_id=?',[$role,$tenant['id'],$id]);if($password!=='')$app->exec('UPDATE users SET password_hash=?,force_password_change=0 WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$id]);}
        else{$app->exec('INSERT INTO users(tenant_id,name,phone,email,username_r17,password_hash,role,is_active,force_password_change) VALUES(?,?,?,?,?,?,?,?,0)',[$tenant['id'],$name,$phone,$email,$alias,password_hash($password,PASSWORD_DEFAULT),$role,$active]);$id=(int)$app->db->lastInsertId();}
        if($employee)$app->exec('UPDATE fisitaap_employees_r17 SET user_id=?,revision=revision+1 WHERE id=? AND tenant_id=?',[$id,$eid,$tenant['id']]);
        qa180_audit($app,$actor,'user_save','user',$id,($old?'Editó':'Creó').' el acceso de '.$name.($employee?' desde el empleado #'.$eid:''));$app->db->commit();return $id;
    }catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();throw $e;}
}
function r19_users_page(App $app,array $actor,array $tenant):void {
    $edit=(int)($_GET['edit']??0);$new=isset($_GET['new']);$formError=false;
    if(is_post()){verify_csrf();try{$edit=r19_users_save($app,$actor,$tenant,$_POST);flash('success','Usuario guardado. Los selectores usan los accesos de este negocio.');redirect(url('admin/usuarios'));}catch(Throwable $e){$formError=true;$new=(int)($_POST['id']??0)===0;$edit=(int)($_POST['id']??0);flash('error',$e instanceof PDOException?'No se guardó. Revisa correo, nombre rápido y empleado.':$e->getMessage());}}
    $rows=$app->all('SELECT u.*,e.id employee_id,e.identification,e.is_active employee_active FROM users u LEFT JOIN fisitaap_employees_r17 e ON e.tenant_id=u.tenant_id AND e.user_id=u.id WHERE u.tenant_id=? AND u.role IN("tenant_admin","manager","editor","cashier","kitchen") ORDER BY u.is_active DESC,u.name,u.id',[$tenant['id']]);$current=null;foreach($rows as $row)if((int)$row['id']===$edit)$current=$row;if($edit&&!$current)throw new DomainException('Usuario no disponible en este negocio.');
    $can=true;try{qa180_permission($app,$actor,'usuarios','write');}catch(DomainException){$can=false;}
    admin_shell_start('Usuarios',$actor,$tenant,'usuarios');echo '<section class="r19-users-head"><div><h2>Accesos de tu negocio</h2><p>Usuarios controla el ingreso y los permisos. Los expedientes se registran primero en Control de personal.</p></div>'.($can?'<a class="btn primary" href="'.e(url('admin/usuarios?new=1')).'">+ Nuevo usuario</a>':'').'</section>';
    if(($new||$current)&&$can){$v=fn($k,$default='')=>$formError?($_POST[$k]??$current[$k]??$default):($current[$k]??$default);$employees=$app->all('SELECT id,name_r19 name,email_r19 FROM fisitaap_employees_r17 WHERE tenant_id=? AND (user_id IS NULL OR user_id=?) ORDER BY is_active DESC,name_r19,id',[$tenant['id'],$current['id']??0]);$employeeId=(int)($formError?($_POST['employee_id']??0):($current['employee_id']??$_GET['employee']??0));$owner=($current['role']??'')==='tenant_admin';
        echo '<section class="card admin-card r19-user-form"><h2>'.($new?'Nuevo usuario':'Editar acceso de '.e($current['name'])).'</h2><form method="post">'.csrf_field().pos_hidden_148('id',$current['id']??0);
        if(!$owner)echo '<label>Empleado'.r2_select('employee_id',$employees,$employeeId,'name',true).'</label><p><a href="'.e(url(module_enabled_v12($app,$tenant,'personnel')?'admin/personal?new=1':'admin/empleados?new=1')).'">Registrar empleado en Control de personal →</a></p>'.(!$employees&&$new?'<p class="alert alert-info">No hay empleados sin acceso. Registra primero a la persona.</p>':'');else echo '<p>Acceso del propietario. Su perfil se conserva.</p><label>Empleado asociado (opcional para marcas)'.r2_select('employee_id',$employees,$employeeId,'name',true).'</label>';
        $contact='';foreach($employees as $e)if((int)$e['id']===$employeeId)$contact=(string)($e['email_r19']??'');echo '<div class="hr17-grid">'.field('Correo único de acceso','email',$v('email',$contact),true,'email').field('Nombre rápido','username',$v('username',$current['username_r17']??''),true).field($new?'Contraseña (desde 4 caracteres)':'Nueva contraseña (vacío para conservar)','password','',$new,'password');
        if(!$owner){$selected=$v('role','cashier');$assignment=$current?$app->one('SELECT previous_role FROM fisitaap_r1_user_roles WHERE tenant_id=? AND user_id=?',[$tenant['id'],$current['id']]):null;if($assignment)$selected=$assignment['previous_role'];echo '<label>Perfil<select class="input" name="role">';foreach(['cashier'=>'Cajero','manager'=>'Gestor','editor'=>'Editor']+(r17_menu($tenant)?['kitchen'=>'Cocina']:[]) as $key=>$label)echo '<option value="'.$key.'" '.($key===$selected?'selected':'').'>'.$label.'</option>';echo '</select></label>';if($assignment)echo '<p>Los permisos del rol personalizado se conservan. Edítalos desde Roles y permisos.</p>';}
        echo '</div>';if(!$owner)echo '<label><input type="checkbox" name="is_active" '.(($formError?isset($_POST['is_active']):($current['is_active']??1))?'checked':'').'> Acceso activo</label>';echo '<footer><a class="btn btn-light" href="'.e(url('admin/usuarios')).'">Volver al listado</a><button class="btn primary">Guardar usuario</button></footer></form></section>';
    }else{echo '<section class="card admin-card"><div class="table-wrap"><table class="table"><thead><tr><th>Persona</th><th>Nombre rápido / correo</th><th>Perfil</th><th>Estado</th><th></th></tr></thead><tbody>';foreach($rows as $row)echo '<tr><td>'.e($row['name']).'<small>'.($row['employee_id']?'Empleado #'.(int)$row['employee_id']:($row['role']==='tenant_admin'?'Propietario':'Acceso anterior · vincular empleado')).'</small></td><td>'.e($row['username_r17']?:'Sin nombre rápido').'<small>'.e($row['email']).'</small></td><td>'.e(restructure_role_name_r1($app,$row)).'</td><td>'.($row['is_active']?'Activo':'Inactivo').'</td><td>'.($can?'<a class="btn btn-light" href="'.e(url('admin/usuarios?edit='.$row['id'])).'">Editar</a>':'').'</td></tr>';echo '</tbody></table></div></section>';}
    admin_shell_end();
}
function r19_employee_identity(App $app,array $tenant,?array $employee):string {
    $v=fn($key,$default='')=>$employee[$key]??$default;$out='<div class="hr17-grid">';foreach(['name'=>'Nombre completo','identification'=>'Cédula / DIMEX / pasaporte','phone'=>'Teléfono','nationality'=>'Nacionalidad','civil_status'=>'Estado civil','sex'=>'Sexo (según identificación contractual)','occupation'=>'Profesión / oficio'] as $key=>$label)$out.=field($label,$key,$v($key,$key==='nationality'?'Costarricense':''),in_array($key,['name','identification'],true));
    $out.=field('Correo de contacto','email',$v('email_r19',$v('email')),false,'email').field('Fecha de nacimiento','birth_date',$v('birth_date'),false,'date').'<label>Sucursal'.r2_select('branch_id',$app->all('SELECT id,name FROM branches WHERE tenant_id=? AND is_active=1 ORDER BY is_default DESC,id',[$tenant['id']]),$v('branch_id')).'</label></div><label>Domicilio<textarea class="input" name="address" rows="2">'.e($v('address')).'</textarea></label><label><input type="checkbox" name="is_active" '.($v('is_active',1)?'checked':'').'> Empleado activo</label><p>Crear un expediente no crea una cuenta. El acceso, contraseña y permisos se administran en <a href="'.e(url('admin/usuarios')).'">Usuarios</a>.</p>';
    return $out;
}
function r19_basic_employees(App $app,array $actor,array $tenant):void {
    qa180_permission($app,$actor,'usuarios','write');$id=(int)($_GET['employee']??0);
    if(is_post()){verify_csrf();$allowed=['csrf','id','revision','name','identification','phone','email','birth_date','nationality','civil_status','sex','occupation','address','branch_id','is_active','job_title','start_date'];$_POST=array_intersect_key($_POST,array_fill_keys($allowed,true));$wasActive=isset($_POST['is_active']);$app->db->beginTransaction();try{if((int)($_POST['id']??0)>0){$_POST+=hr17_employee($app,(int)$tenant['id'],(int)$_POST['id'],true);if(!$wasActive)unset($_POST['is_active']);}$_POST+=['action'=>'save_employee','start_date'=>date('Y-m-d'),'job_title'=>'Colaborador','branch_id'=>physical_branch_v14($app,$tenant)['id']];$id=hr17_save_employee($app,$actor,$tenant);$app->db->commit();flash('success','Empleado guardado. Ahora puedes crear su usuario.');redirect(url('admin/usuarios?new=1&employee='.$id));}catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();flash('error',$e instanceof PDOException?'No se guardó el empleado. Revisa la identificación.':$e->getMessage());}}
    $employee=$id?hr17_employee($app,(int)$tenant['id'],$id):null;admin_shell_start('Control de personal',$actor,$tenant,'usuarios');echo '<section class="card admin-card"><h2>Registro de empleados</h2><p>El registro básico permite crear accesos de personas del negocio. El módulo Control de personal añade horarios, marcas y vacaciones.</p>';
    if(isset($_GET['new'])||$employee||is_post())echo '<form method="post">'.csrf_field().pos_hidden_148('id',$employee['id']??0).pos_hidden_148('revision',$employee['revision']??0).r19_employee_identity($app,$tenant,$employee).field('Puesto','job_title',$employee['job_title']??'',true).field('Fecha de ingreso','start_date',$employee['start_date']??date('Y-m-d'),true,'date').'<button class="btn">Guardar empleado</button></form>';else{echo '<a class="btn" href="'.e(url('admin/empleados?new=1')).'">+ Nuevo empleado</a>';foreach($app->all('SELECT id,name_r19 FROM fisitaap_employees_r17 WHERE tenant_id=? ORDER BY name_r19,id',[$tenant['id']]) as $e)echo '<p><a href="'.e(url('admin/empleados?employee='.$e['id'])).'">'.e($e['name_r19']).'</a></p>';}
    echo '</section>';admin_shell_end();
}
